Na tlačítko klikneš jednou. Co ukáže?

```jsx
function reducer(state, action) {
  switch (action.type) {
    case "inc":
      return state + 1;
    default:
      return state;
  }
}

function Counter() {
  const [count, dispatch] = useReducer(reducer, 0);
  return <button onClick={() => dispatch({ type: "inc" })}>{count}</button>;
}
```

Na tlačítko klikneš jednou. Co ukáže?

```jsx
function reducer(s, a) {
  if (a.type === "add") return s + a.value;
  return s;
}

function Total() {
  const [n, dispatch] = useReducer(reducer, 10);
  return <button onClick={() => dispatch({ type: "add", value: 5 })}>{n}</button>;
}
```
